def test_dedupe_transcripts_keeps_last_record_and_sorts_by_day_then_id():
    first = {"id": "a", "day": 4, "flagged": True}
    last = {"id": "a", "day": 2, "flagged": False}
    same_day = {"id": "b", "day": 2, "flagged": True}
    earlier = {"id": "z", "day": 1, "flagged": None}
    assert dedupe_transcripts([first, same_day, last, earlier]) == [earlier, last, same_day]


